DELETE FROM base_menu WHERE module_id=(SELECT id FROM base_module WHERE name ='CovidModule');
DELETE FROM public.base_module_artifact WHERE module_id=(SELECT id FROM base_module WHERE name ='CovidModule');
DELETE FROM public.base_module_dependencies WHERE module_id=(SELECT id FROM base_module WHERE name ='CovidModule');
DELETE FROM public.base_web_module WHERE module_id=(SELECT id FROM base_module WHERE name ='CovidModule');
DELETE FROM base_module WHERE name ='CovidModule';


CREATE SEQUENCE immunization_id_seq;
CREATE TABLE IF NOT EXISTS public.immunization
(
    id bigint NOT NULL DEFAULT nextval('immunization_id_seq'),
    patient_id bigint,
    patient_uuid character varying(100),
    immunization_type character varying,
    unique_immunization_data character varying,
    vaccination_date date,
    archived integer,
    PRIMARY KEY (id)
);
ALTER SEQUENCE immunization_id_seq OWNED BY immunization.id;
